// Lighthouse consensus-layer block validation of execution payload.
// NOTE: Lighthouse does NOT implement per-transaction gas cap at the consensus layer.
// Individual tx.gasLimit validation is delegated to the execution client via engine_newPayload.
// Lighthouse only validates block-level fields: parent_hash, prev_randao, timestamp, blob count.
pub fn partially_verify_execution_payload<E: EthSpec, Payload: AbstractExecPayload<E>>(
    state: &BeaconState<E>,
    block_slot: Slot,
    body: BeaconBlockBodyRef<E, Payload>,
    spec: &ChainSpec,
) -> Result<(), BlockProcessingError> {
    let payload = body.execution_payload()?;
    if is_merge_transition_complete(state) {
        block_verify!(
            payload.parent_hash() == state.latest_execution_payload_header()?.block_hash(),
            BlockProcessingError::ExecutionHashChainIncontiguous { ... }
        );
    }
    block_verify!(
        payload.prev_randao() == *state.get_randao_mix(state.current_epoch())?,
        BlockProcessingError::ExecutionRandaoMismatch { ... }
    );
    let timestamp = compute_timestamp_at_slot(state, block_slot, spec)?;
    block_verify!(
        payload.timestamp() == timestamp,
        BlockProcessingError::ExecutionInvalidTimestamp { ... }
    );
    // blob_kzg_commitments count check against spec.max_blobs_per_block
    Ok(())
}

