// Lighthouse validators reject blocks via Engine API: engine_newPayload response
// A block with invalid transactions (including oversized tx.gasLimit) will be
// returned as PayloadStatus::Invalid by the EL, causing Lighthouse to reject the block.
async fn notify_new_payload<T: BeaconChainTypes>(
    chain: &Arc<BeaconChain<T>>,
    block: BeaconBlockRef<'_, T::EthSpec>,
) -> Result<PayloadVerificationStatus, BlockError> {
    let new_payload_response = execution_layer.notify_new_payload(block.try_into()?).await;
    match new_payload_response {
        Ok(status) => match status {
            PayloadStatus::Valid => Ok(PayloadVerificationStatus::Verified),
            PayloadStatus::Invalid { ... } => {
                // Block invalidated in fork choice
                Err(BlockError::ExecutionPayloadError(ExecutionPayloadError::RejectedByExecutionEngine { ... }))
            }
        }
    }
}

