// CALLEE: beacon_node/execution_layer/src/lib.rs:expected_gas_limit (lines 2141-2160)
pub fn expected_gas_limit(
    parent_gas_limit: u64,
    target_gas_limit: u64,
    spec: &ChainSpec,
) -> Option<u64> {
    let max_gas_limit_difference = parent_gas_limit
        .checked_div(spec.gas_limit_adjustment_factor)
        .and_then(|result| result.checked_sub(1))
        .unwrap_or(0);
    if target_gas_limit > parent_gas_limit {
        let gas_diff = target_gas_limit.saturating_sub(parent_gas_limit);
        parent_gas_limit.checked_add(std::cmp::min(gas_diff, max_gas_limit_difference))
    } else {
        let gas_diff = parent_gas_limit.saturating_sub(target_gas_limit);
        parent_gas_limit.checked_sub(std::cmp::min(gas_diff, max_gas_limit_difference))
    }
}

// PRIMARY: beacon_node/beacon_chain/src/execution_payload.rs:notify_new_payload (lines 129-225)
// Lighthouse enforces block validity through Engine API engine_newPayload call.
// Private channel transactions (Flashbots, MEV) bypass txpool but are still
// validated by the execution client when Lighthouse calls engine_newPayload.
// If the EL returns PayloadStatus::Invalid, Lighthouse rejects the block.
async fn notify_new_payload<T: BeaconChainTypes>(
    chain: &Arc<BeaconChain<T>>,
    block: BeaconBlockRef<'_, T::EthSpec>,
) -> Result<PayloadVerificationStatus, BlockError> {
    let new_payload_response = execution_layer.notify_new_payload(block.try_into()?).await;
    match new_payload_response {
        Ok(PayloadStatus::Valid) => Ok(PayloadVerificationStatus::Verified),
        Ok(PayloadStatus::Invalid { .. }) => {
            Err(BlockError::ExecutionPayloadError(ExecutionPayloadError::RejectedByExecutionEngine { .. }))
        }
        Err(e) => Err(BlockError::ExecutionPayloadError(
            ExecutionPayloadError::RequestFailed { error: e.into() }
        ))
    }
}

